platform.apilevel = '2.0'

-- ==========================================================
--  Generated by tools/bundle.py -- do not edit this file.
--  Sources: src/connect4/game.lua, src/connect4/main.lua
-- ==========================================================

local Board = (function()
-- game.lua -- pure Connect Four logic, plus the bot that plays it.
--
-- Like the other games here, this module knows nothing about the TI-Nspire:
-- no `platform`, no `gc`, no `timer`. All drawing and input lives in main.lua.
-- The bot lives here too, deliberately: keeping the search as pure logic is
-- what lets the tests drive it to completion synchronously while the handheld
-- runs the very same code in slices.

local Board = {}
Board.__index = Board

local COLS, ROWS, CONNECT = 7, 6, 4
Board.COLS, Board.ROWS, Board.CONNECT = COLS, ROWS, CONNECT

local CELLS = COLS * ROWS

-- Row 1 is the top row, row ROWS the bottom, so gravity fills downwards and
-- the drawing code can walk rows in screen order. Cell (c, r) lives at
-- (r - 1) * COLS + c, written out at each use because these are the hottest
-- lines in the file.

-- The four line directions. Their opposites are covered by scanning both ways
-- from the placed disc, so east/north/north-east/south-east is the whole set.
local DC = { 1, 0, 1, 1 }
local DR = { 0, 1, 1, -1 }

-- Centre-first. Connect Four's branching factor is 7, and a centre disc sits
-- in more of the 69 winning lines than any other, so trying the middle first
-- is what makes alpha-beta's cutoffs cheap.
local ORDER = { 4, 3, 5, 2, 6, 1, 7 }

-- ------------------------------------------------- the positional score ----
--
-- Every four-in-a-row window on the board -- 24 horizontal, 21 vertical and
-- 12 of each diagonal, 69 in all -- flattened to raw cell indices, four in a
-- row per window.
local WINDOWS = (function()
  local w = {}
  local function add(c, r, dc, dr)
    for k = 0, CONNECT - 1 do
      w[#w + 1] = (r + k * dr - 1) * COLS + (c + k * dc)
    end
  end
  for r = 1, ROWS do for c = 1, COLS - 3 do add(c, r, 1, 0) end end
  for r = 1, ROWS - 3 do for c = 1, COLS do add(c, r, 0, 1) end end
  for r = 1, ROWS - 3 do for c = 1, COLS - 3 do add(c, r, 1, 1) end end
  for r = CONNECT, ROWS do for c = 1, COLS - 3 do add(c, r, 1, -1) end end
  return w
end)()
Board.WINDOWS = WINDOWS

local NWINDOWS = #WINDOWS / 4

-- What a window is worth to player 1, by how many discs of each colour sit in
-- it. A window holding both colours can never be completed by either, so it
-- is worth exactly nothing; otherwise near-complete lines are worth a lot more
-- than sparse ones. Antisymmetric by construction: swap the colours and the
-- score negates, which is what lets negamax read one number for both sides.
-- The count-4 entry is only ever passed through: a completed line is a win,
-- and the search scores that before it ever looks at the position.
local WEIGHT = { [0] = 0, 1, 8, 60, 1000 }
local CENTRE = 4 -- per disc in column 4, the one thing the window count misses

-- Indexed by ones * 5 + twos + 1, so a window's contribution is one lookup.
local WSCORE = (function()
  local t = {}
  for a = 0, CONNECT do
    for b = 0, CONNECT do
      local v = 0
      if a > 0 and b == 0 then v = WEIGHT[a]
      elseif b > 0 and a == 0 then v = -WEIGHT[b] end
      t[a * 5 + b + 1] = v
    end
  end
  return t
end)()
Board.WSCORE = WSCORE
Board.CENTRE_WEIGHT = CENTRE

-- Which windows each cell belongs to (between 3 and 13 of them), so placing a
-- disc can patch the running score instead of rescanning all 69. Recomputing
-- the whole board at every leaf was measured at 12us a call against 0.6us for
-- everything else a node does -- it was the search, near enough.
local CELLWIN, CELLWINN = {}, {}
for i = 1, CELLS do CELLWIN[i], CELLWINN[i] = {}, 0 end
for wid = 1, NWINDOWS do
  local base = (wid - 1) * CONNECT
  for k = 1, CONNECT do
    local cell = WINDOWS[base + k]
    local n = CELLWINN[cell] + 1
    CELLWIN[cell][n], CELLWINN[cell] = wid, n
  end
end

-- opts.rand:  function(n) -> integer in [1, n]. Injectable, so tests get a
--             bot whose blunders are reproducible.
-- opts.mode:  "hotseat" (two players on one calculator) or "bot".
--
-- There is no networked mode and there never can be: Nspire Lua has no socket
-- API, no link-cable access and no wireless. Two players means one calculator.
function Board.new(opts)
  opts = opts or {}
  local self = setmetatable({}, Board)
  self.rand = opts.rand or function(n) return math.random(n) end
  self.mode = opts.mode or "bot"
  self.botPlayer = opts.botPlayer or 2
  self.wins = { 0, 0 }
  self.draws = 0
  self:reset(opts.starter)
  return self
end

-- starter: which player moves first, 1 (red) or 2 (yellow).
function Board:reset(starter)
  local cells = {}
  for i = 1, CELLS do cells[i] = 0 end
  self.cells = cells
  self.heights = { 0, 0, 0, 0, 0, 0, 0 }
  -- Discs of each colour per window, packed as ones * 5 + twos, and the
  -- running positional score the two of them add up to. Both are maintained
  -- by place/unplace; an empty board scores zero.
  local wcode = {}
  for i = 1, NWINDOWS do wcode[i] = 0 end
  self.wcode = wcode
  self.score = 0
  self.nplaced = 0
  self.turn = starter or 1
  self.state = "ready" -- ready | playing | paused | won | draw
  self.winner = nil
  self.line = nil      -- the winning run, for highlighting
  self.last = nil      -- { c, r } of the most recent disc
end

-- ------------------------------------------------------------- board reads --

function Board:at(c, r)
  if c < 1 or c > COLS or r < 1 or r > ROWS then return nil end
  return self.cells[(r - 1) * COLS + c]
end

-- True when a disc can physically go in column c. Deliberately says nothing
-- about whose turn it is or whether the game is over -- the search needs the
-- purely geometric question, and Board:drop adds the rules on top.
function Board:open(c)
  if type(c) ~= "number" or c ~= math.floor(c) then return false end
  if c < 1 or c > COLS then return false end
  return self.heights[c] < ROWS
end

-- The row a disc dropped into column c would come to rest in, or nil.
function Board:landing(c)
  if not self:open(c) then return nil end
  return ROWS - self.heights[c]
end

function Board:isFull()
  return self.nplaced >= CELLS
end

function Board:isOver()
  return self.state == "won" or self.state == "draw"
end

-- Centre-first, so the caller that wants "a reasonable move" can take the
-- first entry and the search gets its ordering for free.
function Board:legalMoves(out)
  out = out or {}
  for i = #out, 1, -1 do out[i] = nil end
  for i = 1, COLS do
    local c = ORDER[i]
    if self.heights[c] < ROWS then out[#out + 1] = c end
  end
  return out
end

-- ------------------------------------------------------- make / unmake ------
--
-- The search explores by mutating this board and undoing, rather than copying
-- it: a copy per node would dominate the cost of the search on a handheld.
-- These two are the only writers, and they are exact inverses.

function Board:place(c)
  local p = self.turn
  local h = self.heights[c]
  local r = ROWS - h
  local cell = (r - 1) * COLS + c

  self.cells[cell] = p
  self.heights[c] = h + 1
  self.nplaced = self.nplaced + 1
  self.turn = 3 - p

  local wc, s = self.wcode, self.score
  local list, n = CELLWIN[cell], CELLWINN[cell]
  local step = (p == 1) and 5 or 1
  for k = 1, n do
    local wid = list[k]
    local old = wc[wid]
    local new = old + step
    wc[wid] = new
    s = s + WSCORE[new + 1] - WSCORE[old + 1]
  end
  if c == 4 then s = s + ((p == 1) and CENTRE or -CENTRE) end
  self.score = s

  return r
end

function Board:unplace(c)
  local p = 3 - self.turn
  local h = self.heights[c] - 1
  local r = ROWS - h
  local cell = (r - 1) * COLS + c

  self.cells[cell] = 0
  self.heights[c] = h
  self.nplaced = self.nplaced - 1
  self.turn = p

  local wc, s = self.wcode, self.score
  local list, n = CELLWIN[cell], CELLWINN[cell]
  local step = (p == 1) and 5 or 1
  for k = 1, n do
    local wid = list[k]
    local old = wc[wid]
    local new = old - step
    wc[wid] = new
    s = s + WSCORE[new + 1] - WSCORE[old + 1]
  end
  if c == 4 then s = s - ((p == 1) and CENTRE or -CENTRE) end
  self.score = s
end

-- Copies the part of a position the search cares about into `dst`.
--
-- The bot searches a scratch copy rather than the board being played on. It
-- has to: the search is suspended between timer ticks with several discs
-- still played, and on a shared board those half-explored discs get painted
-- to the screen -- the player watches phantom pieces appear and vanish while
-- the bot thinks. One copy per move is nothing; a copy per node would have
-- cost more than the search.
function Board:copyInto(dst)
  local src, out = self.cells, dst.cells
  for i = 1, CELLS do out[i] = src[i] end
  src, out = self.heights, dst.heights
  for i = 1, COLS do out[i] = src[i] end
  src, out = self.wcode, dst.wcode
  for i = 1, NWINDOWS do out[i] = src[i] end

  dst.nplaced = self.nplaced
  dst.turn = self.turn
  dst.score = self.score
  dst.state = "playing" -- the search only ever asks about live positions
  return dst
end

-- ------------------------------------------------------- win detection ------
--
-- Only a line through the disc that was just played can be new, so both of
-- these scan four directions outward from one cell instead of walking the
-- whole board. tests/connect4/run.lua checks that this finds exactly what a
-- full-board scan finds, at every cell and in every direction.

-- Allocation-free, because the search calls it at every node.
--
-- Assumes p's disc is already sitting at (c, r): it counts that cell as one
-- and scans outward. Every caller asks immediately after placing there, which
-- is the only time the question means anything. Ask it about an empty cell and
-- it will happily count a gap as filled.
function Board:winsAt(c, r, p)
  local cells = self.cells
  for d = 1, 4 do
    local dc, dr = DC[d], DR[d]
    local n = 1

    local cc, rr = c + dc, r + dr
    while cc >= 1 and cc <= COLS and rr >= 1 and rr <= ROWS
        and cells[(rr - 1) * COLS + cc] == p do
      n = n + 1
      cc, rr = cc + dc, rr + dr
    end

    cc, rr = c - dc, r - dr
    while cc >= 1 and cc <= COLS and rr >= 1 and rr <= ROWS
        and cells[(rr - 1) * COLS + cc] == p do
      n = n + 1
      cc, rr = cc - dc, rr - dr
    end

    if n >= CONNECT then return true end
  end
  return false
end

-- The winning run itself, for highlighting. Returns every disc in the run,
-- which is four but can be five or more when a drop joins two groups.
function Board:lineAt(c, r)
  local p = self:at(c, r)
  if not p or p == 0 then return nil end

  for d = 1, 4 do
    local dc, dr = DC[d], DR[d]

    -- Walk back to the start of the run, then collect forwards.
    local sc, sr = c, r
    while self:at(sc - dc, sr - dr) == p do
      sc, sr = sc - dc, sr - dr
    end

    local run = {}
    local cc, rr = sc, sr
    while self:at(cc, rr) == p do
      run[#run + 1] = { c = cc, r = rr }
      cc, rr = cc + dc, rr + dr
    end

    if #run >= CONNECT then return run end
  end
  return nil
end

-- ---------------------------------------------------------------- the game --

function Board:start()
  if self.state == "ready" then self.state = "playing" end
end

function Board:pause()
  if self.state == "playing" then self.state = "paused" end
end

function Board:resume()
  if self.state == "paused" then self.state = "playing" end
end

-- Plays a disc for the player to move. Returns the row it landed in, or nil
-- if the move was illegal (full column, out of range, or game not running).
function Board:drop(c)
  if self.state ~= "playing" then return nil end
  if not self:open(c) then return nil end

  local p = self.turn
  local r = self:place(c)
  self.last = { c = c, r = r }

  if self:winsAt(c, r, p) then
    self.state = "won"
    self.winner = p
    self.line = self:lineAt(c, r)
    self.wins[p] = self.wins[p] + 1
  elseif self:isFull() then
    self.state = "draw"
    self.draws = self.draws + 1
  end
  return r
end

-- ============================================================== the bot =====

local AI = {}
AI.__index = AI
Board.AI = AI

-- Far enough above any positional score that a mate always outranks one, and
-- small enough that WIN_SCORE - ply stays comfortably inside a double.
local WIN_SCORE = 100000
AI.WIN_SCORE = WIN_SCORE

-- Nodes of search the host should spend per timer tick, and the difficulty
-- table those slices add up to.
--
-- The whole point of the incremental search is that this number is bounded: a
-- search that ran to completion inside one on.timer() would freeze the screen
-- and queue up keypresses, which reads to the player as a crash.
--
-- Measured on the build container (tests/connect4/run.lua prints this table):
--
--   depth    1     2     3     4      5      6       7       8
--   nodes    7    26   115   387   1943   4404   14067   23534   (mean, cumulative)
--
-- at ~3.2us a node, so ~310k nodes/sec here. The handheld's 396MHz ARM runs
-- interpreted Lua far slower than this x86 -- call it 50x, which is the one
-- number in this file that is an estimate rather than a measurement -- so
-- ~6k nodes/sec, ~310 nodes in a 0.05s tick. Half of that is the budget:
Board.TICK_NODES = 150

-- Half rather than the third a game loop would want, because overrunning a
-- tick costs almost nothing *here specifically*: while the bot is thinking
-- there is no animation and nothing blinking, so a late timer just means the
-- bot's turn takes a little longer. Even if the 50x estimate is out by two,
-- the failure is a slower bot, not a stuck one.

-- Difficulty is search depth, plus deliberate blunders at the bottom so a
-- beginner can actually win a game.
--
-- maxDepth and nodeBudget are ceilings, not promises: what the bot really
-- gets is thinkTicks * TICK_NODES nodes, and iterative deepening turns that
-- into "the deepest complete search that fit". So the levels are separated by
-- *time* as well as by depth. Measured at 150 nodes a tick, over 40 random
-- midgame positions each (tests/connect4/run.lua prints this one too):
--
--   Easy    10 ticks (0.5s)      34 nodes   depth 2.0
--   Medium  20 ticks (1.0s)    1941 nodes   depth 4.7
--   Hard    40 ticks (2.0s)    5922 nodes   depth 5.6
--   Expert  80 ticks (4.0s)   12000 nodes   depth 6.2
--
-- nodeBudget is what binds instead on a desktop, where the same eighty ticks
-- would otherwise be four seconds of a search that finished in a tenth of one.
Board.LEVELS = {
  { name = "Easy",   maxDepth = 2, blunder = 0.35, nodeBudget = 2000,   thinkTicks = 10 },
  { name = "Medium", maxDepth = 5, blunder = 0.06, nodeBudget = 12000,  thinkTicks = 20 },
  { name = "Hard",   maxDepth = 7, blunder = 0,    nodeBudget = 60000,  thinkTicks = 40 },
  { name = "Expert", maxDepth = 9, blunder = 0,    nodeBudget = 250000, thinkTicks = 80 },
}

function AI.new(board, opts)
  opts = opts or {}
  local self = setmetatable({}, AI)
  -- root is the game's board and is only ever read; board is the scratch copy
  -- the search mutates. See Board:copyInto for why they are not the same one.
  self.root = board
  self.board = Board.new({ rand = board.rand })
  self.maxDepth = opts.maxDepth or 6
  self.nodeBudget = opts.nodeBudget or 40000
  self.blunder = opts.blunder or 0
  self.rand = opts.rand or board.rand
  self.stack = {}
  self.rootOrder = {}
  self.legal = {}
  self:cancel()
  return self
end

function AI.fromLevel(board, level, opts)
  local L = Board.LEVELS[level] or Board.LEVELS[#Board.LEVELS]
  local o = { maxDepth = L.maxDepth, blunder = L.blunder, nodeBudget = L.nodeBudget }
  if opts then for k, v in pairs(opts) do o[k] = v end end
  return AI.new(board, o)
end

-- Puts back every disc the search still has on its scratch board.
--
-- Abandoning an iteration part-way -- which running out of budget does, and
-- which is the normal case on a handheld -- leaves one played disc per live
-- stack frame. begin() copies the position in fresh and would overwrite them
-- anyway, so this is belt and braces: it keeps ai.board a legal position at
-- every moment between calls, which is cheap to hold and unpleasant to debug
-- the absence of. Deepest frame first, because that disc went down last.
function AI:unwind()
  local sp = self.sp or 0
  while sp >= 1 do
    local f = self.stack[sp]
    if f and f.child then
      self.board:unplace(f.child)
      f.child = nil
    end
    sp = sp - 1
  end
  self.sp = 0
end

-- Throws away any search in progress, leaving the board untouched, and
-- readies a fresh one.
function AI:cancel()
  self:unwind()
  self.active = false
  self.done = false
  self.result = nil
  self.sp = 0
  self.nodes = 0
  self.searchDepth = 0
  self.completedDepth = nil
  self.best = nil
  self.bestValue = 0
  self.blundered = false
end

-- Static evaluation from `p`'s point of view; positive is good for p.
--
-- There is no work left to do here: Board:place keeps the score up to date as
-- the search walks, and it is antisymmetric, so one side reads the negation of
-- the other. tests/connect4/run.lua checks it against a full rescan of all 69
-- windows after every move of a long fuzz.
function AI:evaluate(p)
  local s = self.board.score
  if p == 1 then return s end
  return -s
end

-- --------------------------------------------------- the incremental search --
--
-- There are no threads on this machine, and a search that runs to completion
-- inside one on.timer() callback freezes the screen and queues up keypresses,
-- which reads to the player as a crash. So the search is an explicit state
-- machine over its own stack of frames: main.lua calls think(budget) once per
-- tick and the search advances by that many nodes and no more.
--
-- Frames mirror what a recursive negamax would keep in locals:
--   depth     plies left to search below this node
--   alpha,beta  the window, already negated for this side
--   best,bestMove  the best seen so far at this node
--   moves,i   the move list and how far through it we are
--   child     the column currently played on the board, awaiting its value
--   pending   a child's returned value, waiting to be folded in

function AI:frame(n)
  local f = self.stack[n]
  if not f then
    f = {}
    self.stack[n] = f
  end
  return f
end

-- Root move order: last iteration's best first, then centre-out. Searching
-- the previous best first is most of what makes iterative deepening pay for
-- itself rather than just costing extra.
function AI:buildRootOrder()
  local out = self.rootOrder
  for i = #out, 1, -1 do out[i] = nil end
  if self.best then out[1] = self.best end
  for _, c in ipairs(self.legal) do
    if c ~= self.best then out[#out + 1] = c end
  end
  return out
end

function AI:startDepth(d)
  self.searchDepth = d
  self.sp = 1
  local f = self:frame(1)
  f.depth = d
  f.alpha = -math.huge
  f.beta = math.huge
  f.best = -math.huge
  f.bestMove = nil
  f.moves = self:buildRootOrder()
  f.i = 0
  f.child = nil
  f.pending = nil
end

-- Begins a search for whoever is to move. Safe to call on a finished board:
-- it just reports "no move".
function AI:begin()
  self:cancel()
  self.root:copyInto(self.board)
  self.board:legalMoves(self.legal)

  if #self.legal == 0 then
    self.done = true
    return
  end

  -- Centre-most legal column: the fallback that guarantees think() can always
  -- name a legal move, however little work it has been allowed to do.
  self.best = self.legal[1]

  if self.blunder > 0 and self.rand(1000) <= self.blunder * 1000 then
    self.result = self.legal[self.rand(#self.legal)]
    self.blundered = true
    self.done = true
    return
  end

  self.active = true
  self:startDepth(1)
end

-- Pops the top frame, handing `value` to its parent -- or finishing the
-- iteration when the frame that returned was the root.
function AI:ret(value)
  self.sp = self.sp - 1
  if self.sp == 0 then
    self:finishDepth(value)
  else
    self.stack[self.sp].pending = value
  end
end

function AI:finishDepth(value)
  local root = self.stack[1]
  if root.bestMove then
    self.best = root.bestMove
    self.bestValue = value
    self.completedDepth = self.searchDepth
  end

  -- Stop when there is nothing more to learn: the depth cap, a board with
  -- fewer empty cells than that, or a result already forced either way.
  local empties = CELLS - self.board.nplaced
  if self.searchDepth >= self.maxDepth
      or self.searchDepth >= empties
      or self.bestValue >= WIN_SCORE - 1000
      or self.bestValue <= -WIN_SCORE + 1000 then
    self.active = false
    self.done = true
    self.result = self.best
  else
    self:startDepth(self.searchDepth + 1)
  end
end

-- One unit of work: try one move at the current node. Costs at most one node.
function AI:step()
  local f = self.stack[self.sp]
  local board = self.board

  -- A child finished while we were away. Negamax: its value is from the other
  -- side's point of view, so it comes back negated.
  if f.pending ~= nil then
    local v = -f.pending
    f.pending = nil
    board:unplace(f.child)
    f.child = nil
    if v > f.best then
      f.best, f.bestMove = v, f.moves[f.i]
      if v > f.alpha then f.alpha = v end
    end
    if f.alpha >= f.beta then return self:ret(f.best) end
  end

  local moves, heights = f.moves, board.heights
  local i = f.i + 1
  while moves[i] and heights[moves[i]] >= ROWS do i = i + 1 end
  f.i = i

  local c = moves[i]
  if not c then return self:ret(f.best) end

  local p = board.turn
  local r = board:place(c)
  self.nodes = self.nodes + 1

  -- Terminal and horizon cases are scored here rather than in a child frame,
  -- which keeps the stack one level shallower than the nominal depth.
  local v
  if board:winsAt(c, r, p) then
    -- Distance from the root, so a win found sooner beats the same win found
    -- later and the bot actually finishes games off instead of dawdling.
    v = WIN_SCORE - (self.searchDepth - f.depth)
  elseif board:isFull() then
    v = 0
  elseif f.depth <= 1 then
    -- Board:place already folded this move into board.score, so the horizon
    -- evaluation is a sign flip. Inlined because this is the innermost line
    -- of the whole search.
    v = (p == 1) and board.score or -board.score
  end

  if v then
    board:unplace(c)
    if v > f.best then
      f.best, f.bestMove = v, c
      if v > f.alpha then f.alpha = v end
    end
    if f.alpha >= f.beta then return self:ret(f.best) end
    return
  end

  f.child = c
  local g = self:frame(self.sp + 1)
  g.depth = f.depth - 1
  g.alpha = -f.beta
  g.beta = -f.alpha
  g.best = -math.huge
  g.bestMove = nil
  g.moves = ORDER
  g.i = 0
  g.child = nil
  g.pending = nil
  self.sp = self.sp + 1
end

-- Does up to maxNodes nodes of work. Returns the chosen column once the
-- search has settled, or nil to mean "still thinking, call me again".
--
-- Slicing changes nothing about the answer: the budget only ever decides
-- *when* this returns, never *what*. That is worth keeping true -- it is what
-- tests/connect4/run.lua leans on to check the sliced search against the
-- one-shot one.
function AI:think(maxNodes)
  if self.done then return self.result end
  if not self.active then self:begin() end
  if self.done then return self.result end

  local stop = self.nodes + (maxNodes or 500)
  if stop > self.nodeBudget then stop = self.nodeBudget end

  while self.active and self.nodes < stop do
    self:step()
  end

  -- Out of budget part-way through an iteration. Iterative deepening means
  -- the last completed depth has already left a usable move behind, which is
  -- the whole reason the search deepens rather than going straight for
  -- maxDepth: there is always an answer to give.
  if self.active and self.nodes >= self.nodeBudget then
    self:unwind()
    self.active = false
    self.done = true
    self.result = self.best
  end

  return self.result
end

-- Gives up on the iteration in progress and settles for the best move the
-- last completed depth found. main.lua calls this once the bot has used up
-- the ticks its difficulty allows, which is what bounds the bot's turn in
-- *time* on a machine whose speed this code has no way to know.
function AI:stop()
  if self.done then return self.result end
  if not self.active then self:begin() end
  if not self.done then
    self:unwind()
    self.active = false
    self.done = true
    self.result = self.best
  end
  return self.result
end

-- Runs the search out in one go. Used by the tests and by nothing on the
-- handheld, where blocking the event loop is exactly what must not happen.
function AI:solve()
  local mv
  repeat
    mv = self:think(self.nodeBudget)
  until self.done
  return mv
end

return Board
end)()

-- main.lua -- TI-Nspire presentation layer: drawing, input, timing.
--
-- Rules and the bot live in src/connect4/game.lua. `platform.apilevel` is
-- emitted as the first line of the bundle by tools/bundle.py, so it is
-- intentionally absent here.
--
-- When bundled, `Board` is already a local from the inlined module; the
-- `Board or require` form below also lets this file load under a desktop Lua.
local Board = Board or require("game")

-- ------------------------------------------------------------------ tuning --
-- Connect Four is turn-based, so nothing here is a game loop: the timer runs
-- the drop animation and feeds the bot its slices, and asks for a repaint only
-- while one of those is actually happening.
local BASE_TICK       = 0.05 -- host timer period, the practical floor on hardware
local DROP_TICKS      = 5    -- ticks a disc takes to fall, whatever the distance
local MIN_THINK_TICKS = 3    -- shortest visible "thinking" pause, see below

-- Nodes of search per timer tick, and why that number: see the note above
-- Board.TICK_NODES in game.lua, which is where the measurements live. It is
-- kept there rather than here because the difficulty table is calibrated
-- against it, and the tests check that calibration.
local TICK_NODES      = Board.TICK_NODES

-- If the estimate behind it is wrong the bot does not break, it just lands on
-- a different depth: each difficulty caps its turn in *ticks*, and iterative
-- deepening means whatever depth finished inside them is the one that plays.
-- ---------------------------------------------------------------------------

local HUD_H    = 22 -- height of the status bar, pixels
local CURSOR_H = 16 -- strip above the board: the drop cursor, and the result banner
local CELL_MIN = 6
local CELL_MAX = 40 -- past this the board looks silly on a large window

local COLS, ROWS = Board.COLS, Board.ROWS

-- These exact values are the contract with tests/connect4/frame.lua, which
-- reads the board back out of a painted frame rather than out of the game.
local PAGE     = {  18,  21,  27 }
local HUD_BG   = {  30,  34,  44 }
local HUD_RULE = {  58,  64,  80 }
local BOARD_BG = {  38,  78, 180 }
local BOARD_RIM = {  22,  46, 112 } -- the moulded edge around the classic board
local BOARD_HI = {  58, 102, 214 } -- the hovered column
local HOLE     = {  16,  19,  26 }
local PANEL_BG = {  26,  30,  39 }
local RING     = { 255, 255, 255 } -- flashes around the winning four
local INK      = { 224, 228, 238 }
local INK_DIM  = { 138, 146, 164 }

local DISC = {
  [1] = { 226,  66,  60 },
  [2] = { 247, 199,  58 },
}
local NAME = { [1] = "Red", [2] = "Yellow" }

local ui = { w = 318, h = 212, cell = 24, bx = 0, by = HUD_H + CURSOR_H, pad = 3 }

local game = Board.new({ mode = "bot" })
local ai   = nil

-- phase is what the *presentation* is doing, which is not the same question as
-- game.state: the board can be mid-game while the screen is busy dropping a
-- disc or the bot is busy thinking, and input has to be ignored during both.
local phase      = "idle" -- idle | dropping | thinking
local anim       = nil    -- { c, r, p, t } while a disc is falling
local thinkTicks = 0
local cursor     = 4
local blink      = 0
local entropy    = 0      -- ticks idled before the first input; seeds the RNG
local starter    = 1      -- who opens the next round; alternates

local menu = { row = 1, mode = 2, level = 2 } -- mode 1 = hot-seat, 2 = vs bot

local MODE_NAMES  = { "2 Players (hot-seat)", "1 Player vs Computer" }

-- ---------------------------------------------------------------- helpers --

local function col(gc, c) gc:setColorRGB(c[1], c[2], c[3]) end

local function level() return Board.LEVELS[menu.level] end

local function vsBot() return game.mode == "bot" end

local function botPlayer() return game.botPlayer end

-- os.time() alone is a poor seed here: a handheld that has just been reset can
-- report the same value every launch, which would make the bot's blunders --
-- and so every Easy game -- identical every time. Mixing in how long the
-- player sat on the title screen fixes that.
local function reseed()
  local t = 0
  if os and os.time then t = os.time() or 0 end
  if os and os.clock then t = t + math.floor((os.clock() or 0) * 1000) end
  math.randomseed(t + entropy * 7919)
  math.random(); math.random() -- first draws after a reseed are weakly mixed
end

-- True when the machine is waiting on a person rather than on itself.
local function humansTurn()
  return game.state == "playing" and phase == "idle"
    and not (vsBot() and game.turn == botPlayer())
end

local function nearestOpen(c)
  if game:open(c) then return c end
  for d = 1, COLS do
    if game:open(c - d) then return c - d end
    if game:open(c + d) then return c + d end
  end
  return c
end

-- Hands the bot the position and lets on.timer() feed it from there.
local function startThinking()
  if not ai then ai = Board.AI.fromLevel(game, menu.level) end
  ai:cancel()
  thinkTicks = 0
  phase = "thinking"
end

-- Called once a disc has finished falling: hand over to the bot, or to the
-- player, or to nobody if that disc ended the game.
local function afterMove()
  if game:isOver() then
    phase = "idle"
    return
  end
  cursor = nearestOpen(cursor)
  if vsBot() and game.turn == botPlayer() then
    startThinking()
  else
    phase = "idle"
  end
end

local function doDrop(c)
  if phase == "dropping" or game.state ~= "playing" then return false end
  local p = game.turn
  -- The tally the status bar shows while the disc is in the air. A winning
  -- drop bumps it the moment it is committed, and a score that ticks over
  -- before the disc lands gives the result away just as surely as the banner.
  local tally = { game.wins[1], game.wins[2] }
  local r = game:drop(c)
  if not r then return false end
  cursor = c
  anim = { c = c, r = r, p = p, t = 0, wins = tally }
  phase = "dropping"
  return true
end

local function newRound()
  reseed()
  game.mode = (menu.mode == 1) and "hotseat" or "bot"
  game:reset(starter)
  starter = 3 - starter -- alternate the opening move between rounds
  game:start()
  ai = Board.AI.fromLevel(game, menu.level)
  anim, phase, thinkTicks = nil, "idle", 0
  cursor = 4
  if vsBot() and game.turn == botPlayer() then startThinking() end
end

local function toMenu()
  if ai then ai:cancel() end
  -- Clear the board on the way out. Leaving the abandoned game showing behind
  -- the title panel invites the player to think it is still theirs to finish.
  -- The match tally is not part of a round, so it survives.
  game:reset(starter)
  anim, phase = nil, "idle"
  cursor = 4
end

local function togglePause()
  -- Pausing mid-search is fair game and throws the search away; the bot
  -- starts over on resume. Mid-drop it is ignored, because the disc is five
  -- ticks from landing and freezing it in the air looks like a fault.
  if game.state == "playing" and phase ~= "dropping" then
    if phase == "thinking" then
      if ai then ai:cancel() end
      phase = "idle"
    end
    game:pause()
  elseif game.state == "paused" then
    game:resume()
    -- The bot's search was thrown away on the way in, so start it again.
    if vsBot() and game.turn == botPlayer() then startThinking() end
  end
end

local function confirm()
  local s = game.state
  if s == "ready" then
    newRound()
  elseif s == "paused" then
    game:resume()
    if vsBot() and game.turn == botPlayer() then startThinking() end
  elseif game:isOver() then
    newRound()
  elseif humansTurn() then
    doDrop(cursor)
  end
end

-- --------------------------------------------------------------- lifecycle --

-- Called before the first paint, and again if the window is resized -- which
-- on a handheld means never, but the computer software can resize freely.
-- The board is always 7x6, so a resize only ever changes the scale: unlike
-- Snake, there is no reason for it to disturb a game in progress.
function on.resize(w, h)
  ui.w, ui.h = w, h

  -- The extra slack is the moulded rim drawn just outside the board.
  local availW = w - 12
  local availH = h - HUD_H - CURSOR_H - 8
  local cell = math.floor(math.min(availW / COLS, availH / ROWS))
  if cell > CELL_MAX then cell = CELL_MAX end
  if cell < CELL_MIN then cell = CELL_MIN end

  local bw, bh = cell * COLS, cell * ROWS
  ui.cell = cell
  ui.pad = math.max(1, math.floor(cell / 8))
  ui.bx = math.max(0, math.floor((w - bw) / 2))
  ui.by = math.max(HUD_H + CURSOR_H,
                   HUD_H + CURSOR_H + math.floor((h - HUD_H - CURSOR_H - bh) / 2))

  platform.window:invalidate()
end

timer.start(BASE_TICK)

function on.timer()
  blink = blink + 1
  local dirty = false

  if game.state == "ready" or game.state == "paused" then
    entropy = entropy + 1
    if blink % 8 == 0 then dirty = true end

  elseif phase == "dropping" then
    anim.t = anim.t + 1
    dirty = true
    if anim.t >= DROP_TICKS then
      anim = nil
      afterMove()
    end

  elseif phase == "thinking" then
    thinkTicks = thinkTicks + 1
    local mv = ai:think(TICK_NODES)

    -- The turn is capped in ticks, not in nodes, because how many nodes fit in
    -- a tick depends on a machine this code cannot measure. Whatever depth
    -- finished by now is the one that plays.
    if not mv and thinkTicks >= level().thinkTicks then
      mv = ai:stop()
    end

    -- An instant answer -- a forced win, or an Easy-level blunder -- would
    -- otherwise flash past with the board apparently moving on its own, so
    -- hold the indicator up for a few ticks either way.
    if mv and thinkTicks >= MIN_THINK_TICKS then
      phase = "idle"
      if not doDrop(mv) then afterMove() end
    end
    dirty = true

  elseif game:isOver() then
    if blink % 4 == 0 then dirty = true end -- flash the winning four
  end

  if dirty then platform.window:invalidate() end
end

function on.deactivate()
  -- Losing focus mid-search would leave the bot holding a half-finished
  -- search across an unknown gap in time; pausing throws it away cleanly.
  if phase == "thinking" then
    if ai then ai:cancel() end
    phase = "idle"
  end
  game:pause()
  platform.window:invalidate()
end

-- ------------------------------------------------------------------- input --

local function menuKey(key)
  if key == "up" then
    menu.row = (menu.row == 1) and 2 or 1
  elseif key == "down" then
    menu.row = (menu.row == 2) and 1 or 2
  elseif key == "left" or key == "right" then
    local d = (key == "right") and 1 or -1
    if menu.row == 1 then
      menu.mode = (menu.mode == 1) and 2 or 1
    else
      menu.level = ((menu.level - 1 + d) % #Board.LEVELS) + 1
      ai = nil -- rebuilt at the next round, at the new depth
    end
  end
end

function on.arrowKey(key)
  if game.state == "ready" then
    menuKey(key)
  elseif game.state == "paused" or game:isOver() then
    -- Arrows do nothing behind an overlay; enter is the way out.
  elseif key == "left" or key == "right" then
    if humansTurn() then
      local d = (key == "right") and 1 or -1
      local c = cursor
      for _ = 1, COLS do
        c = ((c - 1 + d) % COLS) + 1
        if game:open(c) then break end
      end
      cursor = c
    end
  elseif key == "down" then
    if humansTurn() then doDrop(cursor) end
  end
  platform.window:invalidate()
end

function on.enterKey()
  confirm()
  platform.window:invalidate()
end

function on.escapeKey()
  if game.state == "ready" then
    -- already home
  elseif game:isOver() then
    toMenu()
  else
    togglePause()
  end
  platform.window:invalidate()
end

function on.charIn(ch)
  ch = string.lower(ch or "")
  local n = tonumber(ch)

  if game.state == "ready" then
    -- 1 and 2 pick the mode straight off the title screen.
    if n == 1 or n == 2 then
      menu.mode = (n == 1) and 2 or 1
    elseif ch == " " then
      confirm()
    end

  elseif n and n >= 1 and n <= COLS then
    -- Typing the column number is the fastest way to play on a calculator,
    -- and beats walking the cursor across with the arrow keys.
    if humansTurn() then doDrop(n) end

  elseif ch == " " then
    confirm()
  elseif ch == "a" then
    on.arrowKey("left"); return
  elseif ch == "d" then
    on.arrowKey("right"); return
  elseif ch == "s" then
    on.arrowKey("down"); return
  elseif ch == "p" then
    togglePause()
  elseif ch == "r" then
    if game.state ~= "ready" then newRound() end
  elseif ch == "m" then
    toMenu()
  end

  platform.window:invalidate()
end

function on.mouseDown(x, y)
  if game.state ~= "playing" then
    confirm()
  elseif humansTurn() then
    local c = math.floor((x - ui.bx) / ui.cell) + 1
    if c >= 1 and c <= COLS then
      cursor = c
      doDrop(c)
    end
  end
  platform.window:invalidate()
end

-- ----------------------------------------------------------------- drawing --

local function cellX(c) return ui.bx + (c - 1) * ui.cell end
local function cellY(r) return ui.by + (r - 1) * ui.cell end

-- A game is over the instant the winning disc is committed, but the disc is
-- still in the air for another few ticks. Announcing the result over a disc
-- the player can see falling gives the game away before the board does, so
-- everything that reports the result waits for it to land.
local function resultVisible()
  return game:isOver() and not anim
end

local function statusText()
  if game.state == "ready" then
    return MODE_NAMES[menu.mode]
  elseif game.state == "paused" then
    return "Paused"
  elseif anim then
    return NAME[anim.p] .. " to play"
  elseif game.state == "draw" then
    return "Draw"
  elseif game.state == "won" then
    return NAME[game.winner] .. " wins"
  elseif phase == "thinking" then
    -- The depth is honest information, not decoration: it is how a player can
    -- tell a slow machine from a hard level. It is the depth being searched
    -- now, not the last one finished, so it never reads as zero.
    local d = math.max((ai and ai.searchDepth) or 1, 1)
    return "Thinking d" .. d .. string.rep(".", 1 + (blink % 3))
  end
  return NAME[game.turn] .. " to play"
end

local function drawHud(gc)
  col(gc, HUD_BG)
  gc:fillRect(0, 0, ui.w, HUD_H)
  col(gc, HUD_RULE)
  gc:drawLine(0, HUD_H - 1, ui.w, HUD_H - 1)

  gc:setFont("sansserif", "b", 10)
  local titleW = gc:getStringWidth("CONNECT 4")

  gc:setFont("sansserif", "r", 10)
  local tally = (anim and anim.wins) or game.wins
  local stats = statusText() .. "   " .. tally[1] .. "-" .. tally[2]
  -- Drawn games only earn a place in the tally once one has happened.
  if game.draws > 0 then stats = stats .. "-" .. game.draws end
  local statsW = gc:getStringWidth(stats)
  local statsX = ui.w - statsW - 6

  -- A long status, or a wider font than assumed, can push the status into the
  -- title. The status matters more, so the title is what yields.
  if statsX > titleW + 12 then
    gc:setFont("sansserif", "b", 10)
    col(gc, DISC[1])
    gc:drawString("CONNECT 4", 6, 4, "top")
    gc:setFont("sansserif", "r", 10)
  end

  col(gc, INK)
  local sx = math.max(4, statsX)
  gc:drawString(stats, sx, 4, "top")

  -- A swatch of whose move it is. The status line already says so, but the
  -- colour is the thing a player actually glances at, and it reads at a
  -- distance where 10pt text does not.
  local who = nil
  if anim then who = anim.p
  elseif game.state == "won" then who = game.winner
  elseif game.state == "playing" or game.state == "paused" then who = game.turn end
  if who and sx >= 12 then
    col(gc, DISC[who])
    gc:fillRect(sx - 9, 7, 6, 8)
  end
end

-- The chevron above the board showing where the next disc goes. Drawn out of
-- rectangles rather than an arc so that every fillArc in a frame is a board
-- cell, which is what lets tests/connect4/ui.lua assert that no disc ever
-- escapes the board.
local function drawCursor(gc)
  if game.state ~= "playing" or phase == "dropping" then return end
  if phase ~= "thinking" and not humansTurn() then return end
  if not game:open(cursor) then return end

  local d = ui.cell - 2 * ui.pad
  local h = math.min(CURSOR_H - 3, math.max(3, math.floor(d / 2)))
  local cx = cellX(cursor) + ui.cell / 2
  local top = ui.by - h - 2

  if phase == "thinking" then
    -- A pulsing marker centred over the board, not over a column: the bot has
    -- not chosen one yet, and putting the marker anywhere in particular would
    -- be a guess the player would read as an answer.
    local mid = ui.bx + (ui.cell * COLS) / 2
    col(gc, ((blink % 6) < 3) and DISC[botPlayer()] or HUD_RULE)
    gc:fillRect(math.floor(mid - d / 4), top, math.max(1, math.floor(d / 2)), 2)
    return
  end

  col(gc, DISC[game.turn])
  for i = 0, h - 1 do
    local wRow = math.floor(d * (h - i) / h)
    if wRow > 0 then
      gc:fillRect(math.floor(cx - wRow / 2), top + i, wRow, 1)
    end
  end
end

local function drawBoard(gc)
  local cell, pad = ui.cell, ui.pad
  local bw, bh = cell * COLS, cell * ROWS
  local d = cell - 2 * pad

  -- A darker rim, the way the moulding round a real board reads. Clamped to
  -- the window so a small computer-software window cannot push it off-screen.
  local rim = math.max(1, math.min(3, math.floor(cell / 8)))
  local rx = math.max(0, ui.bx - rim)
  local ry = math.max(0, ui.by - rim)
  col(gc, BOARD_RIM)
  gc:fillRect(rx, ry, math.min(bw + 2 * rim, ui.w - rx), math.min(bh + 2 * rim, ui.h - ry))

  col(gc, BOARD_BG)
  gc:fillRect(ui.bx, ui.by, bw, bh)

  -- The hovered column, lit from behind so the holes still read as holes.
  if humansTurn() and game:open(cursor) then
    col(gc, BOARD_HI)
    gc:fillRect(cellX(cursor), ui.by, cell, bh)
  end

  local lineSet = nil
  if game.line and resultVisible() and (blink % 8) < 5 then
    lineSet = {}
    for _, c in ipairs(game.line) do lineSet[(c.r - 1) * COLS + c.c] = true end
  end

  for r = 1, ROWS do
    for c = 1, COLS do
      local x, y = cellX(c), cellY(r)
      local v = game:at(c, r)

      -- While a disc is falling its destination is still shown empty; the
      -- disc itself is drawn below, in flight. Exactly 42 arcs either way.
      if anim and anim.c == c and anim.r == r then v = 0 end

      -- The highlight is a white disc drawn just under the winning one, so it
      -- shows as a ring. It needs pad > 1 to have anything to show; on a
      -- window small enough that the discs are only a few pixels across it
      -- ends up exactly behind them and the flash is simply lost, which is
      -- the right way for it to fail -- the banner and the status bar still
      -- say who won.
      if v ~= 0 and lineSet and lineSet[(r - 1) * COLS + c] then
        col(gc, RING)
        gc:fillArc(x + 1, y + 1, cell - 2, cell - 2, 0, 360)
      end

      col(gc, (v == 0) and HOLE or DISC[v])
      gc:fillArc(x + pad, y + pad, d, d, 0, 360)
    end
  end

  if anim then
    -- Accelerating rather than linear, because a disc that falls at a
    -- constant speed reads as a slide. It starts at the top row of the board,
    -- never above it, so it is inside the board on every frame.
    local t = anim.t / DROP_TICKS
    if t > 1 then t = 1 end
    local y = cellY(1) + pad + (t * t) * (anim.r - 1) * cell
    col(gc, DISC[anim.p])
    gc:fillArc(cellX(anim.c) + pad, math.floor(y + 0.5), d, d, 0, 360)
  end
end

-- lines: array of { text, dim = bool, sel = bool }.
-- opts.widest: strings a line might later hold, so the panel is sized once for
--   the widest wording it can ever show and does not jitter as the selection
--   moves through the menu.
local function drawPanel(gc, title, lines, accent, opts)
  opts = opts or {}
  gc:setFont("sansserif", "b", 16)
  local titleW = gc:getStringWidth(title)

  gc:setFont("sansserif", "r", 10)
  local maxW = titleW
  for _, l in ipairs(lines) do
    local lw = gc:getStringWidth(l[1])
    if lw > maxW then maxW = lw end
  end
  for _, s in ipairs(opts.widest or {}) do
    local lw = gc:getStringWidth(s)
    if lw > maxW then maxW = lw end
  end

  local pad, lineH = 12, 14
  -- Clamp to the window: the handheld is always wide enough, but the computer
  -- software can be made smaller than the panel's natural size, and the Nspire
  -- clips silently rather than complaining.
  local bw = math.min(maxW + pad * 2, ui.w - 4)
  local bh = math.min(24 + #lines * lineH + pad * 2, ui.h - HUD_H - 4)
  local bx = math.max(2, math.floor((ui.w - bw) / 2))
  local by = math.max(HUD_H + 2, math.floor((ui.h - bh) / 2) + math.floor(HUD_H / 2))

  col(gc, PANEL_BG)
  gc:fillRect(bx, by, bw, bh)
  col(gc, accent)
  gc:drawRect(bx, by, bw, bh)

  gc:setFont("sansserif", "b", 16)
  gc:drawString(title, bx + math.floor((bw - titleW) / 2), by + pad - 2, "top")

  gc:setFont("sansserif", "r", 10)
  local y = by + pad + 22
  local lit = (blink % 16) < 10
  for _, l in ipairs(lines) do
    if l.sel then
      col(gc, accent)
    elseif l.dim and not lit then
      col(gc, INK_DIM)
    elseif l.dim then
      col(gc, INK)
    else
      col(gc, INK_DIM)
    end
    gc:drawString(l[1], bx + math.floor((bw - gc:getStringWidth(l[1])) / 2), y, "top")
    y = y + lineH
  end
end

-- A slim bar in the strip above the board, which is where a finished game
-- says what to press. A modal panel in the middle of the screen would sit
-- right on top of the winning four, and that is the one thing worth looking
-- at when a game ends.
local function drawBanner(gc, text, accent)
  local bh = math.min(CURSOR_H, ui.by - HUD_H - 2)
  if bh < 10 then return end -- no room; the status bar still says who won

  gc:setFont("sansserif", "r", 10)
  -- Shorten rather than overflow: the handheld fits the long form, but the
  -- computer software can be dragged narrower than any of them.
  for _, candidate in ipairs({ text, "enter: again    M: menu", "enter / M" }) do
    text = candidate
    if gc:getStringWidth(text) <= ui.w - 20 then break end
  end

  local tw = gc:getStringWidth(text)
  local bw = math.min(tw + 16, ui.w - 4)
  local bx = math.max(2, math.floor((ui.w - bw) / 2))
  local by = math.max(HUD_H + 1, ui.by - bh - 1)

  col(gc, PANEL_BG)
  gc:fillRect(bx, by, bw, bh)
  col(gc, accent)
  gc:drawRect(bx, by, bw, bh)
  col(gc, INK)
  gc:drawString(text, bx + math.floor((bw - tw) / 2), by + math.floor((bh - 11) / 2), "top")
end

local function drawOverlay(gc)
  local s = game.state

  if s == "ready" then
    -- The angle brackets go on the selected row only, so it is obvious which
    -- one Left/Right will change.
    local function row(label, text, selected)
      if selected then return label .. ": < " .. text .. " >" end
      return label .. ":  " .. text
    end

    local modeLine  = row("Mode", MODE_NAMES[menu.mode], menu.row == 1)
    local levelLine = row("Level", level().name, menu.row == 2)

    -- Every wording either row can take, so the panel is sized once for the
    -- widest and stays put while the player scrolls through them.
    local widest = {}
    for _, m in ipairs(MODE_NAMES) do widest[#widest + 1] = row("Mode", m, true) end
    for _, L in ipairs(Board.LEVELS) do widest[#widest + 1] = row("Level", L.name, true) end

    drawPanel(gc, "CONNECT 4", {
      { modeLine,  sel = (menu.row == 1) },
      { levelLine, sel = (menu.row == 2), dim = (menu.mode == 1) },
      { "Up/Down pick a row, Left/Right change it" },
      { "In play: arrows or 1-7, enter to drop" },
      { "Press enter to play", dim = true },
    }, DISC[1], { widest = widest })

  elseif s == "paused" then
    drawPanel(gc, "PAUSED", {
      { NAME[game.turn] .. " to play" },
      { "enter: resume     M: menu", dim = true },
    }, { 240, 190, 70 })

  elseif s == "won" and resultVisible() then
    -- The status bar already names the winner and carries the tally, and the
    -- four discs are flashing on the board, so all that is left to say is
    -- which key does what.
    drawBanner(gc, "enter: play again    M: menu", DISC[game.winner])

  elseif s == "draw" and resultVisible() then
    drawBanner(gc, "A draw -- enter: again    M: menu", { 240, 190, 70 })

  end
end

function on.paint(gc)
  col(gc, PAGE)
  gc:fillRect(0, 0, ui.w, ui.h)
  drawBoard(gc)
  drawCursor(gc)
  drawHud(gc)
  drawOverlay(gc)
end
